llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Neotame, a peptide-like molecule with a free carboxylate and amide bonds, is at least 34.3% systemically available after oral dosing in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zafirlukast, a complex oral drug containing amide, sulfonamide, carbamate, and methoxyaryl groups, has an estimated human oral bioavailability of about 35%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Idasanutlin, despite a carboxylic acid and complex amide/aromatic structure, shows 40.1% absolute oral bioavailability in patients with solid tumors, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Sacubitril, a carboxylic-acid/amide-containing drug with high transferability, has an estimated absolute oral bioavailability of 60% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Letermovir, which shares carboxylic acid, amide, and methoxyaryl features with the query, has an estimated absolute bioavailability of 93.8% in healthy participants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tianeptine, a carboxylic-acid-containing drug with high transferability, is rapidly and completely absorbed orally with about 99% absolute bioavailability in healthy young subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "One idasanutlin record reports 18.7% absolute bioavailability for a microprecipitated bulk powder formulation in the fed state, a formulation/condition-specific value below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a moderately polar carboxylic-acid/amide/urea-containing molecule. High-transferability experimental analogues—neotame (34%), zafirlukast (35%), idasanutlin (40%), sacubitril (60%), letermovir (94%), and tianeptine (99%)—consistently show oral bioavailability at or above 20%, with only one formulation-specific fed-state idasanutlin value below threshold. Therefore the query is predicted to have high absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "No permeability, efflux-transporter, or solubility data specific to the query.",
    "Some records report systemic availability rather than true absolute bioavailability versus IV.",
    "Formulation, dose, and fed/fasted conditions can alter F, as seen with idasanutlin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

